BEGIN;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"service_role"}',true);
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
CREATE TEMP TABLE work_security_fixtures(label text PRIMARY KEY,id uuid NOT NULL DEFAULT gen_random_uuid());
INSERT INTO work_security_fixtures(label) VALUES ('leader'),('head_a'),('head_b'),('member'),('pending'),('dept_a'),('dept_b'),('project_b'),('task_a'),('task_b'),('sub_a'),('submission'),('task_submission');
GRANT SELECT ON work_security_fixtures TO authenticated;
CREATE TEMP TABLE work_security_results(check_name text PRIMARY KEY,passed boolean NOT NULL);
GRANT INSERT,SELECT ON work_security_results TO authenticated;
INSERT INTO auth.users(id,email,raw_user_meta_data) SELECT id,'work-security-'||id::text||'@example.invalid','{"display_name":"Work security fixture"}'::jsonb FROM work_security_fixtures WHERE label IN ('leader','head_a','head_b','member','pending');
UPDATE public.profiles SET approval_status='active' WHERE id IN (SELECT id FROM work_security_fixtures WHERE label IN ('leader','head_a','head_b','member'));
UPDATE public.profiles SET role='super_admin' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='leader');
INSERT INTO public.departments(id,name,head_id) SELECT id,'Work security A',(SELECT id FROM work_security_fixtures WHERE label='head_a') FROM work_security_fixtures WHERE label='dept_a';
INSERT INTO public.departments(id,name,head_id) SELECT id,'Work security B',(SELECT id FROM work_security_fixtures WHERE label='head_b') FROM work_security_fixtures WHERE label='dept_b';
INSERT INTO public.projects(id,name,department_id) SELECT id,'Work security B',(SELECT id FROM work_security_fixtures WHERE label='dept_b') FROM work_security_fixtures WHERE label='project_b';
CREATE FUNCTION pg_temp.work_assert(check_name text,passed boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF passed IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED %',check_name; END IF; INSERT INTO work_security_results VALUES(check_name,true); END; $$;
CREATE FUNCTION pg_temp.work_denied(check_name text,statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN insufficient_privilege THEN PERFORM pg_temp.work_assert(check_name,true); RETURN; END; RAISE EXCEPTION 'Allowed forbidden statement: %',check_name; END; $$;
CREATE FUNCTION pg_temp.work_actor(label text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE actor uuid; BEGIN SELECT id INTO actor FROM work_security_fixtures f WHERE f.label=work_actor.label; PERFORM set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true); PERFORM set_config('request.jwt.claim.sub',actor::text,true); END; $$;
SET LOCAL ROLE authenticated;
SELECT pg_temp.work_actor('leader');
INSERT INTO public.tasks(id,title,department_id,created_by,status) SELECT id,'Work security A',(SELECT id FROM work_security_fixtures WHERE label='dept_a'),auth.uid(),'assigned' FROM work_security_fixtures WHERE label='task_a';
INSERT INTO public.tasks(id,title,department_id,created_by,status) SELECT id,'Work security B',(SELECT id FROM work_security_fixtures WHERE label='dept_b'),auth.uid(),'assigned' FROM work_security_fixtures WHERE label='task_b';
SELECT pg_temp.work_assert('leader creates task and exact audit',(SELECT count(*)=1 AND bool_and(actor_id=auth.uid()) FROM public.task_history WHERE task_id=(SELECT id FROM work_security_fixtures WHERE label='task_a') AND action='create_task'));
SELECT pg_temp.work_denied('leader cannot spoof creator',$q$ INSERT INTO public.tasks(title,created_by) VALUES('spoof',(SELECT id FROM work_security_fixtures WHERE label='member')) $q$);
SELECT pg_temp.work_denied('initial status cannot be approved',$q$ INSERT INTO public.tasks(title,created_by,status) VALUES('spoof',auth.uid(),'approved') $q$);
SELECT pg_temp.work_actor('member');
SELECT pg_temp.work_denied('member cannot create unrelated task',$q$ INSERT INTO public.tasks(title,created_by,department_id) VALUES('spoof',auth.uid(),(SELECT id FROM work_security_fixtures WHERE label='dept_a')) $q$);
SELECT pg_temp.work_denied('member cannot create subtask',$q$ INSERT INTO public.subtasks(task_id,title,created_by) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),'spoof',auth.uid()) $q$);
UPDATE public.tasks SET title='spoofed update' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_a');
SELECT pg_temp.work_assert('member cannot bypass creation guard by update',(SELECT title='Work security A' FROM public.tasks WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_a')));
SELECT pg_temp.work_denied('member cannot forge history',$q$ INSERT INTO public.task_history(task_id,action,actor_id) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),'president_approve',(SELECT id FROM work_security_fixtures WHERE label='leader')) $q$);
SELECT pg_temp.work_denied('member cannot call trigger function',$q$ SELECT fpc_private.record_work_history() $q$);
SELECT pg_temp.work_actor('pending');
SELECT pg_temp.work_denied('pending cannot create task',$q$ INSERT INTO public.tasks(title,created_by) VALUES('spoof',auth.uid()) $q$);
SELECT pg_temp.work_denied('pending cannot create subtask',$q$ INSERT INTO public.subtasks(task_id,title,created_by) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),'spoof',auth.uid()) $q$);
SELECT pg_temp.work_denied('pending cannot write history',$q$ INSERT INTO public.task_history(task_id,action,actor_id) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),'approved',auth.uid()) $q$);
SELECT pg_temp.work_actor('head_b');
SELECT pg_temp.work_denied('other head cannot create subtask',$q$ INSERT INTO public.subtasks(task_id,title,created_by) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),'spoof',auth.uid()) $q$);
SELECT pg_temp.work_actor('head_a');
INSERT INTO public.tasks(title,department_id,created_by,status) VALUES('Work security calendar',(SELECT id FROM work_security_fixtures WHERE label='dept_a'),auth.uid(),'assigned');
SELECT pg_temp.work_assert('head calendar task works',(SELECT count(*)=1 FROM public.tasks WHERE title='Work security calendar' AND created_by=auth.uid()));
SELECT pg_temp.work_denied('head cannot attach unrelated project',$q$ INSERT INTO public.tasks(title,department_id,project_id,created_by,status) VALUES('spoof',(SELECT id FROM work_security_fixtures WHERE label='dept_a'),(SELECT id FROM work_security_fixtures WHERE label='project_b'),auth.uid(),'assigned') $q$);
INSERT INTO public.subtasks(id,task_id,title,created_by,assignee_id,status) SELECT id,(SELECT id FROM work_security_fixtures WHERE label='task_a'),'Work security subtask',auth.uid(),(SELECT id FROM work_security_fixtures WHERE label='member'),'todo' FROM work_security_fixtures WHERE label='sub_a';
SELECT pg_temp.work_assert('head creates subtask and exact audit',(SELECT count(*)=1 AND bool_and(actor_id=auth.uid()) FROM public.task_history WHERE task_id=(SELECT id FROM work_security_fixtures WHERE label='task_a') AND action='create_subtask'));
SELECT pg_temp.work_denied('head cannot reparent subtask',$q$ UPDATE public.subtasks SET task_id=(SELECT id FROM work_security_fixtures WHERE label='task_b') WHERE id=(SELECT id FROM work_security_fixtures WHERE label='sub_a') $q$);
SELECT pg_temp.work_denied('head cannot move task to another department',$q$ UPDATE public.tasks SET department_id=(SELECT id FROM work_security_fixtures WHERE label='dept_b') WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_a') $q$);
SELECT pg_temp.work_denied('head cannot directly approve task',$q$ UPDATE public.tasks SET status='approved' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_a') $q$);
UPDATE public.tasks SET status='working' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_a');
SELECT pg_temp.work_assert('real status change has exact audit',(SELECT count(*)=1 AND bool_and(actor_id=auth.uid() AND old_status='assigned' AND new_status='working') FROM public.task_history WHERE task_id=(SELECT id FROM work_security_fixtures WHERE label='task_a') AND action='task_status_changed'));
UPDATE public.tasks SET status='working' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_a');
SELECT pg_temp.work_assert('no duplicate audit on no-op',(SELECT count(*)=1 FROM public.task_history WHERE task_id=(SELECT id FROM work_security_fixtures WHERE label='task_a') AND action='task_status_changed'));
SELECT pg_temp.work_actor('member');
UPDATE public.subtasks SET status='submitted' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='sub_a');
SELECT pg_temp.work_assert('assignee status and audit remain',(SELECT count(*)=1 AND bool_and(actor_id=auth.uid() AND new_status='submitted') FROM public.task_history WHERE task_id=(SELECT id FROM work_security_fixtures WHERE label='task_a') AND action='update_subtask'));
SELECT pg_temp.work_denied('assignee cannot reassign',$q$ UPDATE public.subtasks SET assignee_id=(SELECT id FROM work_security_fixtures WHERE label='head_b') WHERE id=(SELECT id FROM work_security_fixtures WHERE label='sub_a') $q$);
SELECT pg_temp.work_denied('member cannot inject approved review audit',$q$ INSERT INTO public.task_submissions(task_id,head_id,status,reviewed_by) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),auth.uid(),'approved',(SELECT id FROM work_security_fixtures WHERE label='leader')) $q$);
SELECT pg_temp.work_denied('member cannot impersonate parent head',$q$ INSERT INTO public.task_submissions(task_id,head_id,status) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),auth.uid(),'pending') $q$);
SELECT pg_temp.work_denied('member cannot insert own score',$q$ INSERT INTO public.submissions(subtask_id,member_id,score) VALUES((SELECT id FROM work_security_fixtures WHERE label='sub_a'),auth.uid(),10) $q$);
SELECT pg_temp.work_denied('member cannot insert reviewer metadata',$q$ INSERT INTO public.submissions(subtask_id,member_id,scored_by,scored_at) VALUES((SELECT id FROM work_security_fixtures WHERE label='sub_a'),auth.uid(),(SELECT id FROM work_security_fixtures WHERE label='leader'),now()) $q$);
INSERT INTO public.submissions(id,subtask_id,member_id,file_url,file_name,is_rejected,submitted_at) SELECT id,(SELECT id FROM work_security_fixtures WHERE label='sub_a'),auth.uid(),'https://example.invalid/fixture','fixture',false,now()+interval '1 year' FROM work_security_fixtures WHERE label='submission';
SELECT pg_temp.work_assert('assignee submits with server timestamp',(SELECT count(*)=1 AND bool_and(submitted_at<=statement_timestamp()) FROM public.submissions WHERE id=(SELECT id FROM work_security_fixtures WHERE label='submission')));
SELECT pg_temp.work_assert('per-file insert has exact audit',(SELECT count(*)=1 AND bool_and(actor_id=auth.uid()) FROM public.task_history WHERE metadata->>'record_id'=(SELECT id::text FROM work_security_fixtures WHERE label='submission')));
SELECT pg_temp.work_actor('head_b');
SELECT pg_temp.work_denied('unassigned member cannot submit',$q$ INSERT INTO public.submissions(subtask_id,member_id,is_rejected) VALUES((SELECT id FROM work_security_fixtures WHERE label='sub_a'),auth.uid(),false) $q$);
SELECT pg_temp.work_actor('head_a');
UPDATE public.submissions SET score=8,scored_by=(SELECT id FROM work_security_fixtures WHERE label='leader'),scored_at=now()+interval '1 year' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='submission');
SELECT pg_temp.work_assert('parent head scores and server derives reviewer',(SELECT score=8 AND scored_by=auth.uid() AND scored_at<=statement_timestamp() FROM public.submissions WHERE id=(SELECT id FROM work_security_fixtures WHERE label='submission')));
SELECT pg_temp.work_denied('review cannot move submission parent',$q$ UPDATE public.submissions SET member_id=(SELECT id FROM work_security_fixtures WHERE label='head_b') WHERE id=(SELECT id FROM work_security_fixtures WHERE label='submission') $q$);
SELECT pg_temp.work_denied('head cannot preapprove final submission',$q$ INSERT INTO public.task_submissions(task_id,head_id,status) VALUES((SELECT id FROM work_security_fixtures WHERE label='task_a'),auth.uid(),'approved') $q$);
INSERT INTO public.task_submissions(id,task_id,head_id,status,submitted_at) SELECT id,(SELECT id FROM work_security_fixtures WHERE label='task_a'),auth.uid(),'pending',now()+interval '1 year' FROM work_security_fixtures WHERE label='task_submission';
SELECT pg_temp.work_assert('head submits unreviewed server-timestamp record',(SELECT status='pending' AND reviewed_by IS NULL AND submitted_at<=statement_timestamp() FROM public.task_submissions WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_submission')));
SELECT pg_temp.work_actor('leader');
UPDATE public.task_submissions SET status='approved',reviewed_by=(SELECT id FROM work_security_fixtures WHERE label='head_a'),reviewed_at=now()+interval '1 year' WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_submission');
SELECT pg_temp.work_assert('leader review derives actual identity',(SELECT status='approved' AND reviewed_by=auth.uid() AND reviewed_at<=statement_timestamp() FROM public.task_submissions WHERE id=(SELECT id FROM work_security_fixtures WHERE label='task_submission')));
SELECT pg_temp.work_assert('review has exactly one audit row',(SELECT count(*)=1 AND bool_and(actor_id=auth.uid() AND new_status='approved') FROM public.task_history WHERE metadata->>'record_id'=(SELECT id::text FROM work_security_fixtures WHERE label='task_submission') AND metadata->>'operation'='UPDATE'));
SELECT count(*) AS checks_passed,bool_and(passed) AS all_passed FROM work_security_results;
ROLLBACK;
